package com.mall.controller.admin;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.mall.common.result.PageResult; import com.mall.common.result.Result; import com.mall.controller.CustomerServiceTicketController; import com.mall.entity.CustomerServiceMessage; import com.mall.entity.CustomerServiceTicket; import com.mall.service.CustomerServiceTicketService; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/service-tickets") public class AdminCustomerServiceTicketController { private final CustomerServiceTicketService service; public AdminCustomerServiceTicketController(CustomerServiceTicketService service){this.service=service;} @GetMapping public Result<PageResult<CustomerServiceTicket>> page(@RequestParam(defaultValue="1")Integer current,@RequestParam(defaultValue="20")Integer size,@RequestParam(required=false)Integer status){Page<CustomerServiceTicket>p=service.pageForAdmin(current,size,status);return Result.success(new PageResult<>(p.getTotal(),p.getRecords(),current,size));} @GetMapping("/{id}/messages") public Result<List<CustomerServiceMessage>> messages(@PathVariable Long id){return Result.success(service.messages(null,id,true));} @PostMapping("/{id}/messages") public Result<Void> reply(@AuthenticationPrincipal Long adminId,@PathVariable Long id,@RequestBody CustomerServiceTicketController.MessageRequest r){service.reply(adminId,id,"ADMIN",r.content(),true);return Result.success("回复成功",null);} @PostMapping("/{id}/close") public Result<Void> close(@AuthenticationPrincipal Long adminId,@PathVariable Long id){service.close(adminId,id);return Result.success("已结案",null);} }
